<?php
require __DIR__ . '/config/bootstrap.php';
require_once __DIR__ . '/includes/layout.php';
$user=require_login(); $office=setting($pdo); $today=date('Y-m-d');
$stmt=$pdo->prepare('SELECT * FROM presensi WHERE user_id=? AND tanggal=?'); $stmt->execute([$user['id'],$today]); $attendance=$stmt->fetch();
$recent=$pdo->prepare('SELECT tanggal,jam_masuk,jam_pulang,status,menit_terlambat FROM presensi WHERE user_id=? ORDER BY tanggal DESC LIMIT 7'); $recent->execute([$user['id']]);
page_header('Presensi GPS');
if ($user['role']!=='karyawan') { echo '<div class="alert alert-info">Akun admin tidak melakukan presensi karyawan.</div>'; page_footer(); exit; }
