<?php else: ?><div class="alert alert-success">Presensi hari ini lengkap.<div class="small">Masuk <?= e($attendance['jam_masuk']) ?> · Pulang <?= e($attendance['jam_pulang']) ?></div></div><?php endif; ?>
<div class="small text-secondary mt-3">Jam kerja <?= e(substr($office['jam_masuk']??'08:00',0,5)) ?>–<?= e(substr($office['jam_pulang']??'17:00',0,5)) ?> · toleransi <?= (int)($office['toleransi_menit']??0) ?> menit</div></section>
<section class="panel"><h2 class="h6 fw-bold mb-3">Riwayat terbaru</h2><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Tanggal</th><th>Masuk</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $r): ?><tr><td><?= e(date('d/m',strtotime($r['tanggal']))) ?></td><td><?= e($r['jam_masuk']??'—') ?></td><td><?= e(ucfirst($r['status'])) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
