<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" integrity="sha256-p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY=" crossorigin="anonymous" referrerpolicy="no-referrer"><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js" integrity="sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=" crossorigin="anonymous" referrerpolicy="no-referrer"></script>
<script>
(()=>{const office={lat:<?= json_encode((float)$office['latitude']) ?>,lng:<?= json_encode((float)$office['longitude']) ?>,radius:<?= (int)$office['radius_meter'] ?>},officeName=<?= json_encode((string)($office['nama_kantor']??'Kantor'),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;let map,position=null,selfie=null,stream=null;
const status=document.getElementById('location-status'),distBox=document.getElementById('distance-card'),button=document.getElementById('submit-attendance'),video=document.getElementById('camera-video'),canvas=document.getElementById('camera-canvas'),previewWrap=document.getElementById('selfie-preview-wrap');
if(window.L){map=L.map('attendance-map').setView([office.lat,office.lng],16);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'}).addTo(map);L.marker([office.lat,office.lng]).addTo(map).bindPopup(officeName);L.circle([office.lat,office.lng],{radius:office.radius,color:'#176b59',fillColor:'#42a889',fillOpacity:.16}).addTo(map);}
function haversine(a,b){const r=6371000,rad=x=>x*Math.PI/180,dlat=rad(b.lat-a.lat),dlng=rad(b.lng-a.lng),x=Math.sin(dlat/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(dlng/2)**2;return Math.round(r*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x)));}
function updateButton(){if(button)button.disabled=!position||!stream||video.videoWidth===0||video.videoHeight===0||position.accuracy>100||haversine(position,office)>office.radius;}
function locate(){if(!navigator.geolocation){status.textContent='Browser tidak mendukung GPS.';return}status.textContent='Mencari lokasi?';navigator.geolocation.getCurrentPosition(p=>{position={lat:p.coords.latitude,lng:p.coords.longitude,accuracy:p.coords.accuracy};const d=haversine(position,office),accurate=Number.isFinite(position.accuracy)&&position.accuracy>=0&&position.accuracy<=100;status.textContent=`Akurasi ?${Math.round(position.accuracy)} m`;distBox.className='alert '+(d<=office.radius&&accurate?'alert-success':'alert-warning');distBox.textContent=!accurate?`Akurasi GPS ?${Math.round(position.accuracy)} meter; perlu 100 meter atau lebih baik untuk presensi.`:d<=office.radius?`Anda berada ${d} meter dari kantor dan masuk radius presensi.`:`Anda berjarak ${d} meter dari kantor (radius ${office.radius} meter).`;updateButton();if(map){if(window.userMarker)map.removeLayer(window.userMarker);window.userMarker=L.circleMarker([position.lat,position.lng],{radius:8,color:'#1677ff',fillColor:'#1677ff',fillOpacity:.9}).addTo(map).bindPopup('Lokasi perangkat');map.fitBounds(L.latLngBounds([[office.lat,office.lng],[position.lat,position.lng]]).pad(.25));}},e=>{status.textContent=e.code===1?'Izin lokasi ditolak. Aktifkan akses GPS di browser.':'Lokasi gagal ditemukan. Coba lagi di area terbuka.';position=null;updateButton()},{enableHighAccuracy:true,timeout:15000,maximumAge:0});}
document.getElementById('locate-btn').addEventListener('click',locate);
document.getElementById('camera-btn').addEventListener('click',async()=>{try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});video.srcObject=stream;video.classList.remove('d-none');await video.play();updateButton();}catch(e){Swal.fire('Kamera tidak tersedia','Izinkan akses kamera dan buka aplikasi melalui localhost atau HTTPS.','warning')}});
document.getElementById('retake-btn').addEventListener('click',()=>{selfie=null;previewWrap.classList.add('d-none');video.classList.remove('d-none');updateButton();});
if(button)button.addEventListener('click',async()=>{if(!position||!stream){Swal.fire('Belum siap','Periksa GPS dan aktifkan kamera terlebih dahulu.','info');return}canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);selfie=canvas.toDataURL('image/jpeg',.82);document.getElementById('selfie-preview').src=selfie;previewWrap.classList.remove('d-none');video.classList.add('d-none');button.disabled=true;const confirm=await Swal.fire({title:'Konfirmasi presensi',text:'Kirim lokasi dan selfie untuk presensi '+button.dataset.action+'?',imageUrl:selfie,imageWidth:180,showCancelButton:true,confirmButtonText:'Kirim presensi',cancelButtonText:'Batal'});if(!confirm.isConfirmed){selfie=null;previewWrap.classList.add('d-none');video.classList.remove('d-none');button.disabled=false;return}try{const response=await fetch('/hris-presensi/api/attendance.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({action:button.dataset.action,latitude:position.lat,longitude:position.lng,accuracy:position.accuracy,selfie})});const data=await response.json();if(!response.ok||!data.ok)throw new Error(data.message||'Presensi gagal.');await Swal.fire('Berhasil',data.message,'success');location.reload()}catch(err){await Swal.fire('Presensi gagal',err.message,'error');selfie=null;previewWrap.classList.add('d-none');video.classList.remove('d-none');button.disabled=false}});
})();
</script>
<?php page_footer(); ?>
